import React from "react";
import { useTranslation } from "react-i18next";

export default function Contact() {
  const { t,  } = useTranslation();

  return (
    <div>
      <div className="title-container-white">
        <strong>{t("CONTACT.TITLE")}</strong>
      </div>

      <div>
        <p className="body-container-black">
          {t("CONTACT.CITY")} {t("CONTACT.CITY_DESCRIPTION")}
          <br />
          {t("CONTACT.EMAIL")}{" "}
          {t("CONTACT.EMAIL_DESCRIPTION")}
          <br />
          {t("CONTACT.SITE")}{" "}          
          <a href="https://alberto-zavala.com/" target="blank">
          {t("CONTACT.SITE_DESCRIPTION")}
          </a>
        </p>
      </div>
    </div>
  );
}
