import React, { useState, useEffect } from "react";
import Profile from "../../components/pages/profile/Profile";
import Contact from "../../components/pages/contact/Contact";
import About from "../../components/pages/about/About";
import Skills from "../../components/pages/skills/Skills";
import Experiences from "../../components/pages/experiences/Experiences";
import Education from "../../components/pages/education/Eductaion";
import Certificates from "../../components/pages/certificates/Certificates";
import Language from "../../components/pages/language/Language";
// import Portfolio from "../../components/pages/portfolio/Portfolio";

const windowWidthBreakPointLimit = 992;

export default function Home() {
  const [width, setWidth] = useState(window.innerWidth);
  //const [height, setHeight] = useState(window.innerHeight);

  const updateDimensions = () => {
    setWidth(window.innerWidth);
    //setHeight(window.innerHeight);
  };

  useEffect(() => {
    window.addEventListener("resize", updateDimensions);
    return () => window.removeEventListener("resize", updateDimensions);
  }, []);

  return (
    <div className="main-container">
      <div className="row same-height">
        {width <= windowWidthBreakPointLimit ? (
          <div className="col s12 m12 l4  darken-4 left-menu">
            <Language />
            <Profile />
            <Contact />
            <Skills />
          </div>
        ) : (
          <div className="col s12 m12 l4  darken-4 left-menu">
            <Profile />
            <Contact />
            <Skills />
          </div>
        )}

        {width > windowWidthBreakPointLimit ? (
          <div className="col s12 m12 l8 white">
            <Language />
            <About />
            <Experiences />
            <Certificates />
            {/* <Portfolio /> */}
            <Education />
          </div>
        ) : (
          <div className="col s12 m12 l8 white">
            <About />
            <Experiences />
            <Certificates />
            {/* <Portfolio /> */}
            <Education />
          </div>
        )}
      </div>
    </div>
  );
}
