import React from 'react';
import ProfileImage from '../../images/avatar.png';
import { useTranslation } from 'react-i18next';

export default function Profile() {
    const { t,  } = useTranslation();

    return (
        <div>
            <div className="avatar-img">
                    <img className="circle responsive-img"
                        src={ProfileImage}
                        alt="Alberto Zavala"
                    />
                </div>
                <div className="card body-container-black  darken-4 z-depth-0 hide-on-large-only">
                    <div className="card-content center social">
                        <h6 className="title-container-white">
                            <strong>{t('RESUME.SHORT_NAME')}</strong>
                        </h6>                        
                        <h5 className="white-text text-lighten-1">
                            {t('RESUME.TITLE')}
                        </h5>
                        {/* <a href="https://facebook.com" target="blank">
                            <i className="white-text fab fa-facebook-square fa-2x"></i>
                        </a>

                        <a href="https://twitter.com" target="blank">
                            <i className="white-text fab fa-twitter-square fa-2x"></i>
                        </a> */}

                        <a href="https://linkedin.com" target="blank">
                            <i className="white-text fab fa-linkedin fa-2x"></i>
                        </a>

                        <a href="https://github.com" target="blank">
                            <i className="white-text fab fa-github-square fa-2x"></i>
                        </a>

                        <a href="https://alberto-zavala.com" target="blank">
                            <i className="white-text fa fa-globe-americas fa-2x"></i>
                        </a>
                        
                    </div>
                </div>

                <div className="title-container-white">                    
                    <strong>{t('PROFILE.TITLE')}</strong>                                
                </div>

                <div>
                    <p className="body-container-black">
                            {t('PROFILE.DESCRIPTION_ROW_01')}
                            <br/>
                            {t('PROFILE.DESCRIPTION_ROW_02')}
                            <br/>
                            {t('PROFILE.DESCRIPTION_ROW_03')}
                            <br/>
                        </p>
                </div>
        </div>
    )
}